public WebServer getWebServer(ServletContextInitializer... initializers) {
		JettyEmbeddedWebAppContext context = new JettyEmbeddedWebAppContext();
		context.getContext().getServletContext().setExtendedListenerTypes(true);
		int port = Math.max(getPort(), 0);
		InetSocketAddress address = new InetSocketAddress(getAddress(), port);
		Server server = createServer(address);
		context.setServer(server);
		TempDirs tempDirs = new TempDirs(port);
		server.addEventListener(new CleanTempDirsListener(tempDirs));
		configureWebAppContext(context, tempDirs, initializers);
		server.setHandler(addHandlerWrappers(context));
		logger.info("Server initialized with port: " + port);
		if (this.getMaxConnections() > -1) {
			server.addBean(new NetworkConnectionLimit(this.getMaxConnections(), server.getConnectors()));
		}
		if (Ssl.isEnabled(getSsl())) {
			customizeSsl(server, address);
		}
		for (JettyServerCustomizer customizer : getServerCustomizers()) {
			customizer.customize(server);
		}
		if (this.isUseForwardHeaders()) {
			new ForwardHeadersCustomizer(true).customize(server);
		}
		else if (this.isUseRfcForwardHeader()) {
			new ForwardHeadersCustomizer(false).customize(server);
		}
		if (getShutdown() == Shutdown.GRACEFUL) {
			GracefulHandler gracefulHandler = new GracefulHandler();
			gracefulHandler.setHandler(server.getHandler());
			server.setHandler(gracefulHandler);
		}
		return getJettyWebServer(server);
	},0,spring-boot,941045a2f4db88207f3475e25753a58cf50e3943,module/spring-boot-jetty/src/main/java/org/springframework/boot/jetty/servlet/JettyServletWebServerFactory.java

