public void customize(NettyReactiveWebServerFactory factory) {
		if (getOrDeduceUseForwardHeaders()) {
			configureForwardedSupport(factory);
		}
		PropertyMapper map = PropertyMapper.get();
		map.from(this.nettyProperties::getConnectionTimeout)
			.to((connectionTimeout) -> customizeConnectionTimeout(factory, connectionTimeout));
		map.from(this.nettyProperties::getIdleTimeout).to((idleTimeout) -> customizeIdleTimeout(factory, idleTimeout));
		map.from(this.nettyProperties::getMaxKeepAliveRequests)
			.to((maxKeepAliveRequests) -> customizeMaxKeepAliveRequests(factory, maxKeepAliveRequests));
		if (this.serverProperties.getHttp2().isEnabled()) {
			map.from(this.serverProperties.getMaxHttpRequestHeaderSize())
				.to((size) -> customizeHttp2MaxHeaderSize(factory, size.toBytes()));
		}
		customizeRequestDecoder(factory, map);
	},0,spring-boot,66a093dbfa8129d717604cb0e2ad5947ec52863e,module/spring-boot-reactor-netty/src/main/java/org/springframework/boot/reactor/netty/autoconfigure/NettyReactiveWebServerFactoryCustomizer.java

