static int ordinalIndexOf(final CharSequence str, final CharSequence searchStr, final int ordinal, final boolean lastIndex) {
        if (str == null || searchStr == null || ordinal <= 0) {
            return INDEX_NOT_FOUND;
        }
        if (isEmpty(searchStr)) {
            return lastIndex ? str.length() : 0;
        }
        int found = 0;
        // set the initial index beyond the end of the string
        // this is to allow for the initial index decrement/increment
        int index = lastIndex ? str.length() : INDEX_NOT_FOUND;
        do {
            if (lastIndex) {
                index = CharSequenceUtils.lastIndexOf(str, searchStr, index - 1); // step backwards through string
            } else {
                index = CharSequenceUtils.indexOf(str, searchStr, index + 1); // step forwards through string
            }
            if (index < 0) {
                return index;
            }
            found++;
        } while (found < ordinal);
        return index;
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

static String join(final int[] array, final char delimiter, final int startIndex, final int endIndex) {
        // See StringUtilsJoinBenchmark
        if (array == null) {
            return null;
        }
        checkFromToIndex(startIndex, endIndex, array.length);
        final int count = endIndex - startIndex;
        if (count <= 0) {
            return EMPTY;
        }
        final byte maxElementChars = 11; // "-2147483648"
        final StringBuilder stringBuilder = capacity(count, maxElementChars);
        stringBuilder.append(array[startIndex]);
        for (int i = startIndex + 1; i < endIndex; i++) {
            stringBuilder.append(delimiter).append(array[i]);
        }
        return stringBuilder.toString();
    },1,commons-lang,a1c12e6d4887d66d2112def35d6109905806410d,src/main/java/org/apache/commons/lang3/StringUtils.java

