private HttpServer createHttpServer() {
		HttpServer server = HttpServer.create().bindAddress(this::getListenAddress);
		Ssl ssl = getSsl();
		if (Ssl.isEnabled(ssl)) {
			server = customizeSslConfiguration(server, ssl);
		}
		if (getCompression() != null && getCompression().getEnabled()) {
			CompressionCustomizer compressionCustomizer = new CompressionCustomizer(getCompression());
			server = compressionCustomizer.apply(server);
		}
		server = configureForwardedHeaders(server.protocol(listProtocols()));
		return applyCustomizers(server);
	},0,spring-boot,66a093dbfa8129d717604cb0e2ad5947ec52863e,module/spring-boot-reactor-netty/src/main/java/org/springframework/boot/reactor/netty/NettyReactiveWebServerFactory.java

